css:
@page {
    size: A4;
    margin: 15mm 10mm 15mm 10mm;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 9pt;
    line-height: 1.3;
    color: #000;
}

/* Page break handling */
@media print {
    .page-break {
        page-break-after: always;
        page-break-inside: avoid;
    }

    table.items {
        page-break-inside: auto;
    }

    table.items tr {
        page-break-inside: avoid;
        page-break-after: auto;
    }

    thead {
        display: table-header-group;
    }

    tfoot {
        display: table-footer-group;
    }
}

.clearfix::after {
    content: "";
    display: table;
    clear: both;
}

/* Header Section */
.invoice-header {
    width: 100%;
    margin-bottom: 15px;
    padding-bottom: 10px;
}

.company-info {
    float: left;
    width: 45%;
    font-size: 9pt;
    line-height: 1.4;
}

.company-info img {
    max-width: 120px;
    max-height: 60px;
    margin-bottom: 5px;
}

.invoice-title-box {
    float: right;
    width: 50%;
    text-align: center;
}

.invoice-title {
    border: 2px solid #000;
    padding: 12px 20px;
    font-weight: bold;
    font-size: 16pt;
    letter-spacing: 1px;
}

.page-number {
    text-align: center;
    font-size: 9pt;
    margin: 10px 0;
    clear: both;
}

/* Shipping Info Section */
.shipping-section {
    width: 100%;
    margin: 15px 0;
    font-size: 9pt;
}

.ship-to-box {
    float: left;
    width: 48%;
}

.invoice-details-box {
    float: right;
    width: 48%;
    text-align: right;
}

.freight-forwarder-box {
    float: left;
    width: 48%;
    margin-top: 15px;
}

.section-title {
    font-weight: bold;
    margin-bottom: 5px;
}

.detail-line {
    margin: 2px 0;
}

/* Items Table */
table.items {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    font-size: 8pt;
}

table.items th {
    border: 1px solid #000;
    padding: 6px 4px;
    background-color: #e8e8e8;
    font-weight: bold;
    text-align: center;
    vertical-align: middle;
}

table.items td {
    border: 1px solid #000;
    padding: 5px 4px;
    text-align: center;
    vertical-align: middle;
}

table.items td.align-left {
    text-align: left;
}

table.items td.align-right {
    text-align: right;
}

/* Summary Section */
.summary-section {
    width: 100%;
    margin-top: 20px;
}

.summary-left {
    float: left;
    width: 50%;
    font-size: 9pt;
}

.summary-right {
    float: right;
    width: 45%;
    text-align: right;
    font-size: 9pt;
}

.summary-line {
    margin: 3px 0;
}

.summary-line strong {
    display: inline-block;
    min-width: 150px;
}

/* Footer Notes */
.footer-notes {
    margin-top: 25px;
    font-size: 7.5pt;
    line-height: 1.5;
    text-align: justify;
}

.footer-notes p {
    margin-bottom: 10px;
}

/* Stamp and Signature */
.stamp-section {
    text-align: center;
    margin-top: 30px;
}

.stamp-section img {
    max-width: 80px;
    max-height: 80px;
    margin-bottom: 10px;
}

.signature-line {
    margin-top: 10px;
    font-size: 9pt;
}
